import fs from 'node:fs';import assert from 'node:assert/strict';import {stripTypeScriptTypes} from 'node:module';import * as ref from './src/black-hole-reference.ts';import {saveUniverse,loadUniverse} from './src/sandbox-state.ts';
const checks=[];function check(name,f){try{f();checks.push({name,pass:true})}catch(e){checks.push({name,pass:false,error:e.message})}}
const source=fs.readFileSync('src/ui/inspector.ts','utf8');const fn=stripTypeScriptTypes(source.slice(source.indexOf('export function setBlackHoleReference')).replace('export ',''));let history=0,render=0;const set=new Function('recordHistory','updateInspector','toast','referenceForPreset','referencePickerValue','describeReference',fn+';return setBlackHoleReference')(()=>history++,()=>render++,()=>{},ref.referenceForPreset,ref.referencePickerValue,ref.describeReference);
const b={kind:'blackhole',name:'Test',mass:600,radius:2,velocity:[1,2,3],position:[4,5,6]};
check('actual setter changes reference only and records once',()=>{const before=JSON.stringify(b);set(b,'large-stellar');assert.equal(ref.referenceSolarMasses(b.mass,b.bhReference),30);const {bhReference,...rest}=b;assert.equal(JSON.stringify(rest),before);assert.equal(history,1);assert.equal(render,1)});
check('same preset does not add history; non-hole ignored',()=>{set(b,'large-stellar');set({kind:'star'},'small-stellar');assert.equal(history,1)});
check('fixed factor scales mass and horizon linearly',()=>{b.mass=1200;assert.equal(ref.referenceSolarMasses(b.mass,b.bhReference),60);assert.match(ref.describeReference(b.mass,b.bhReference),/177 km/)});
check('actual setter clears reference with one history step',()=>{set(b,'none');assert.equal(b.bhReference,undefined);assert.equal(history,2)});
check('four merger cases and input immutability',()=>{const a=ref.referenceForPreset('large-stellar',600),c=ref.referenceForPreset('small-stellar',200);const old=JSON.stringify([a,c]);assert.equal(ref.referenceSolarMasses(800,ref.mergeReferences(600,a,200,c)),35);assert.equal(ref.referenceSolarMasses(800,ref.mergeReferences(600,a,200,undefined)),40);assert.equal(ref.referenceSolarMasses(800,ref.mergeReferences(600,undefined,200,c)),20);assert.equal(ref.mergeReferences(600,undefined,200,undefined),undefined);assert.equal(JSON.stringify([a,c]),old)});
check('actual storage JSON roundtrip and sanitize boundary',()=>{const map=new Map();globalThis.localStorage={setItem:(k,v)=>map.set(k,v),getItem:k=>map.get(k)??null};const good=ref.referenceForPreset('large-stellar',600);assert.equal(saveUniverse({version:1,bodies:[{kind:'blackhole',bhReference:good}]}),true);const saved=loadUniverse().bodies[0];assert.deepEqual(ref.sanitizeReference(saved.bhReference,saved.kind),good);assert.equal(ref.sanitizeReference(saved.bhReference,'star'),undefined);assert.equal(ref.sanitizeReference(undefined,'blackhole'),undefined);assert.equal(ref.sanitizeReference({origin:'merged',solarMassPerModelUnit:Infinity},'blackhole'),undefined)});
check('dimensional conversion scales with time squared and length cubed',()=>{assert.equal(ref.gravitationalParameterSim(5,4,2),10);assert.equal(ref.gravitationalParameterSim(5,8,2),40);assert.equal(ref.gravitationalParameterSim(5,4,4),1.25)});
fs.writeFileSync('reviewer-reference-output.json',JSON.stringify({head:'3ab737fe90991767b3cebf5410dc5a1c3b7a6f84',checks,scope:'Real pure functions and extracted setter with stubbed history/DOM feedback; real storage JSON with in-memory localStorage. No rendered browser or full history rebuild execution.'},null,2)+'\n');console.log(checks);if(checks.some(c=>!c.pass))process.exitCode=1;
